  part def Controller {
    in attribute io_0 : Boolean;
    attribute previousPressed : Boolean := true;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign previousPressed := io_0;
      }
      then if (not ((io_0) and ((not previousPressed)))) {
        first start;
        then assign previousPressed := io_0;
      }
    }
    out attribute serial_0_trigger : Boolean = (if io_0 ? true else false);
    out attribute serial_0_value_0 : Integer = (if io_0 ? 1 else 0);
  }
